// WaterWatch prototype — SIMULATED design prototype. No network, no backend. All data synthetic.
(()=>{
const $=(s,r=document)=>r.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ic=(n,c='')=>`<svg class="i ${c}" aria-hidden="true"><use href="#i-${n}"/></svg>`;
const kes=c=>'KES '+(c/100).toLocaleString('en-KE',{maximumFractionDigits:0});
const T0=Date.now();
const st={lang:'en',offline:false,queue:[],audit:[],rep:{cat:null,photo:false,asset:null,gps:false,step:0,t0:null,done:null},sel:null,fStatus:'all',fType:'all',q:'',theme:null,toast:[],anSel:'outages'};
WW.wos.forEach(w=>w.slaEnd=T0+w.slaMin*60000);
WW.reports.forEach(r=>{r.at=r.at});
const asset=id=>WW.assets.find(a=>a.id===id);const tech=id=>WW.techs.find(t=>t.id===id);
const log=(who,act,obj)=>{st.audit.unshift({t:new Date(),who,act,obj});};
log('system','Prototype loaded — synthetic fixtures','—');
['R-2037→WO-318 linked','Role "Dispatcher" assigned WO-318 → Peter Otieno (synthetic)'].forEach(a=>log('Dispatcher (synthetic)',a,'WO-318'));
// ---- status visuals: shape + icon + text, never colour alone
const shapes={operational:'<circle cx="12" cy="12" r="9"/><path d="M7.500 12.500l3 3 6-6.500" class="g"/>',degraded:'<path d="M12 3l10 18H2z"/><path d="M12 10v5" class="g"/>',down:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M8 8l8 8M16 8l-8 8" class="g"/>',contam:'<path d="M12 1.500l10.500 10.500L12 22.500 1.500 12z"/><path d="M12 7v6M12 16v.5" class="g"/>',unknown:'<circle cx="12" cy="12" r="9" stroke-dasharray="3 3" fill="none"/><path d="M9.500 9.500a2.700 2.700 0 1 1 3.500 2.500c-.8.400-1 .8-1 1.800" class="g" fill="none"/>'};
const col={operational:'ok',degraded:'warn',down:'bad',contam:'contam',unknown:'unk'};
const stIcon=(s,sz=16)=>`<svg class="mk" width="${sz}" height="${sz}" viewBox="0 0 24 24" aria-hidden="true" style="fill:var(--${col[s]}-soft);stroke:var(--${col[s]});stroke-width:2.200;stroke-linejoin:round">${shapes[s].replace(/class="g"/g,`style="fill:none;stroke:var(--${col[s]});stroke-width:2.500"`)}</svg>`;
const chip=(s,label)=>`<span class="chip ${s==='contam'?'contam':s}">${s in col?stIcon(s,14):ic({new:'clock',assigned:'user',in_progress:'wrench',parts:'clock',done:'check',linked:'check',ok:'check',late:'clock',flatline:'alert',missing:'wifi-off',P1:'alert',P2:'alert',P3:'clock'}[s]||'clock')}${esc(label)}</span>`;
const stChip=s=>chip(s,WW.statusLabel[s]);
const woLabel={new:'New',assigned:'Assigned',in_progress:'In progress',parts:'Awaiting parts',done:'Completed'};
const sensLabel={ok:'Reporting',late:'Late',missing:'Missing readings',flatline:'Flat-lined'};
const ago=ms=>{const m=Math.round((Date.now()-ms)/60000);return m<60?m+' min ago':m<1440?Math.round(m/60)+' h ago':Math.round(m/1440)+' d ago'};
const mins=m=>{const a=Math.abs(m);const s=a>=1440?Math.floor(a/1440)+'d '+Math.floor(a%1440/60)+'h':a>=60?Math.floor(a/60)+'h '+(a%60)+'m':a+'m';return s};
const slaTxt=w=>{if(w.status==='done')return'';const m=Math.round((w.slaEnd-Date.now())/60000);return m<0?`<span class="sla breach">${ic('alert')} SLA breached ${mins(m)} ago</span>`:`<span class="sla ${m<120?'soon':''}">${ic('clock')} SLA in ${mins(m)}</span>`};
const toast=m=>{const d=document.createElement('div');d.className='toast';d.textContent=m;$('#toasts').append(d);$('#live').textContent=m;setTimeout(()=>d.remove(),3500)};
const openDlg=h=>{const d=$('#dlg');d.innerHTML=h;d.showModal()};const closeDlg=()=>{const d=$('#dlg');if(d.open)d.close()};
const theme=()=>{document.documentElement.dataset.theme=st.theme||''; if(!st.theme)delete document.documentElement.dataset.theme};
// ---- map
const mapSVG=(sel,small)=>{
 const links=WW.links.map(([a,b])=>{const A=asset(a),B=asset(b);return`<line x1="${A.x*7.2}" y1="${A.y*5.2}" x2="${B.x*7.2}" y2="${B.y*5.2}" stroke="var(--line-strong)" stroke-width="3" stroke-linecap="round"/>`}).join('');
 const vis=assetsFiltered();const ids=new Set(vis.map(a=>a.id));
 const ms=WW.assets.map(a=>{const dim=!ids.has(a.id);return`<g class="marker ${sel===a.id?'sel':''}" tabindex="0" role="button" data-act="selAsset" data-id="${a.id}" aria-label="${esc(a.name)}, ${WW.statusLabel[a.status]}" transform="translate(${a.x*7.2},${a.y*5.2})" opacity="${dim?.25:1}"><circle class="ring" r="20"/><svg x="-14" y="-14" width="28" height="28" viewBox="0 0 24 24" style="fill:var(--${col[a.status]}-soft);stroke:var(--${col[a.status]});stroke-width:2.200;stroke-linejoin:round">${shapes[a.status].replace(/class="g"/g,`style="fill:none;stroke:var(--${col[a.status]});stroke-width:2.500"`)}</svg>${a.sensor?`<circle cx="13" cy="-13" r="4.500" fill="var(--brand)" stroke="var(--surface)" stroke-width="1.500"/>`:''}${small?'':`<text y="30" text-anchor="middle" font-size="11" font-weight="700" fill="var(--ink)" paint-order="stroke" stroke="var(--sunken)" stroke-width="3">${esc(a.name.replace(/ \(.*/,'').slice(0,22))}</text>`}</g>`}).join('');
 return`<svg class="map" viewBox="0 0 640 416" role="group" aria-label="Schematic map of assets in Kijani County (synthetic)"><path d="M0 330C120 300 200 360 300 320S520 250 640 300V416H0Z" fill="var(--brand-soft)" opacity=".6"/><path d="M60 40L580 30 610 380 40 390Z" fill="none" stroke="var(--line-strong)" stroke-dasharray="6 6" stroke-width="2"/><path d="M0 230C150 210 250 260 360 220S560 150 640 190" fill="none" stroke="var(--brand)" stroke-width="10" opacity=".35"/><text x="520" y="170" font-size="12" fill="var(--ink-2)" font-style="italic">R. Kijani (schematic)</text>${links}${ms}</svg>`};
const legend=()=>`<ul class="legend" style="list-style:none;margin:0;padding:8px 0">${Object.keys(WW.statusLabel).map(s=>`<li>${stIcon(s,18)} ${WW.statusLabel[s]}</li>`).join('')}<li><svg width="14" height="14" aria-hidden="true"><circle cx="7" cy="7" r="5" fill="var(--brand)"/></svg> Has sensor (simulated)</li></ul>`;
function assetsFiltered(){return WW.assets.filter(a=>(st.fStatus==='all'||a.status===st.fStatus)&&(st.fType==='all'||a.type===st.fType)&&(!st.q||(a.name+a.id).toLowerCase().includes(st.q.toLowerCase())))}
const spark=(s,w=300,h=70)=>{const pts=s.series;const v=pts.filter(x=>x!==null);const mn=Math.min(...v),mx=Math.max(...v),r=mx-mn||1;const X=i=>6+i*(w-12)/(pts.length-1),Y=v=>h-8-(v-mn)/r*(h-16);let d='',gap=false,last=null;pts.forEach((p,i)=>{if(p===null){gap=true;return}d+=(gap||d===''?'M':'L')+X(i).toFixed(1)+' '+Y(p).toFixed(1)+' ';gap=false;last=i});const missStart=pts.findIndex(p=>p===null);
 return`<svg class="spark" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(s.kind)} sensor, last 24 hours. ${s.state==='missing'?'Readings missing for the last 10 hours.':s.state==='flatline'?'Values flat-lined for the last 12 hours.':'Normal variation.'}"><path d="${d}" fill="none" stroke="var(--chart-a)" stroke-width="2.500"/>${missStart>=0?`<rect x="${X(missStart)}" y="2" width="${w-6-X(missStart)}" height="${h-4}" fill="var(--bad-soft)" stroke="var(--bad)" stroke-dasharray="4 3"/>${w<250?"":`<text x="${X(missStart)+6}" y="18" font-size="11" font-weight="700" fill="var(--bad)">No readings</text>`}`:''}${s.state==='flatline'&&w>=250?`<text x="${w-130}" y="14" font-size="11" font-weight="700" fill="var(--warn)">Flat-lined (stuck?)</text>`:''}</svg>`};
// ---- shell
const logo=`<svg viewBox="0 0 32 32" aria-hidden="true"><rect width="32" height="32" rx="8" fill="var(--brand)"/><path d="M16 5c4 5 7 8.500 7 12.500a7 7 0 0 1-14 0C9 13.500 12 10 16 5z" fill="var(--on-brand)"/><path d="M10 19h12M12 22.500h8" stroke="var(--brand)" stroke-width="2"/></svg>`;
const openReports=()=>WW.reports.filter(r=>r.status==='new').length;
function top(route){
 const v=[['console','Utility console'],['report','Report a fault'],['tech','Technician']];const cur=route[0]==='home'?'':route[0];
 return`<header class="top"><a class="logo" href="#/">${logo}WaterWatch</a><nav class="views" aria-label="Prototype views">${v.map(([k,l])=>`<a href="#/${k}" ${cur===k?'aria-current="page"':''}>${l}</a>`).join('')}</nav><span class="spacer"></span><span class="sim">Simulated — design prototype · Synthetic demonstration data</span><button class="btn sm" data-act="theme" aria-label="Toggle light and dark theme">${ic('sun')} Theme</button></header>`}
const nav=[['map','map','Map & assets'],['reports','alert','Outage reports'],['orders','board','Work orders'],['sensors','signal','Sensor health'],['analytics','chart','Analytics'],['audit','log','Audit log']];
function consoleShell(sub,body){
 const badge=k=>k==='reports'&&openReports()?`<span class="badge" aria-label="${openReports()} new">${openReports()}</span>`:'';
 const isCur=k=>sub===k||(sub==='asset'&&k==='map');
 return`<div class="console"><nav class="rail" aria-label="Console"><small>${WW.org.county}</small>${nav.map(([k,i,l])=>`<a href="#/console/${k}" ${isCur(k)?'aria-current="page"':''}>${ic(i)}${l}${badge(k)}</a>`).join('')}</nav><main id="main" tabindex="-1">${body}</main></div><nav class="mobtabs" aria-label="Console">${nav.slice(0,5).map(([k,i,l])=>`<a href="#/console/${k}" ${isCur(k)?'aria-current="page"':''}>${ic(i)}${l.split(' ')[0]}</a>`).join('')}</nav>`}
// ---- views
function home(){return`<main id="main" class="home"><h1>WaterWatch — operations console and community fault reporting</h1><p class="hint">Design prototype for ${esc(WW.org.name)} (fictional) in ${esc(WW.org.county)} (fictional). Everything is simulated; sensors are labelled SIMULATED SENSOR — test environment.</p><div class="homegrid"><a href="#/console/map"><h2>${ic('map')} Utility manager console</h2><p>Map-first asset status, outage triage, work-order board, sensor health, analytics.</p></a><a href="#/report"><h2>${ic('drop-off')} Community fault report</h2><p>Photo + location + category in under 45 seconds. Offline queue. Swahili / English.</p></a><a href="#/tech"><h2>${ic('wrench')} Technician app</h2><p>Job list, navigate, update status, record materials and costs, completion photo.</p></a></div></main>`}
function mapView(id){
 const list=assetsFiltered();const a=id?asset(id):null;
 const count=s=>WW.assets.filter(x=>x.status===s).length;
 return consoleShell('map',`<div class="pagehead"><h1>Map & assets</h1><span class="chip sim">Synthetic demonstration data</span></div>
 <div class="kpis"><div class="kpi"><b>${WW.assets.length}</b><span>Registered assets</span></div><div class="kpi"><b>${count('operational')}</b><span>Operational</span></div><div class="kpi"><b>${count('degraded')+count('down')}</b><span>Degraded or out of service</span></div><div class="kpi"><b>${count('contam')}</b><span>Contamination alert</span></div><div class="kpi"><b>${WW.wos.filter(w=>w.status!=='done'&&w.slaEnd<Date.now()).length}</b><span>Work orders past SLA</span></div></div>
 ${count('contam')?`<div class="alertbar" role="alert">${ic('alert')}<div><b>Contamination alert at Kwa Mama Njeri Water Point (A-006).</b> <span>Reported ${ago(WW.reports[0].at)} by a verified reporter. Not lab-confirmed. WO-320 (P1) awaiting assignment.</span> <a href="#/console/reports">Open triage</a></div></div>`:''}
 <div class="split"><section aria-label="Map"><div class="filters"><div><label for="fs" class="sr">Status</label><select id="fs" data-act="fStatus"><option value="all">All statuses</option>${Object.entries(WW.statusLabel).map(([k,v])=>`<option value="${k}" ${st.fStatus===k?'selected':''}>${v}</option>`).join('')}</select></div><div><label for="ft" class="sr">Type</label><select id="ft" data-act="fType"><option value="all">All asset types</option>${Object.entries(WW.types).map(([k,v])=>`<option value="${k}" ${st.fType===k?'selected':''}>${v}</option>`).join('')}</select></div><div><label for="fq" class="sr">Search</label><input id="fq" type="search" placeholder="Search name or ID" value="${esc(st.q)}" data-act="fQ"></div></div>
 <div class="mapwrap">${mapSVG(id,false)}<span class="mapnote">Schematic map — no tiles. Production: self-hosted Leaflet + configurable tile provider (attributed).</span></div>${legend()}</section>
 <section aria-label="Asset list and detail">${a?assetCard(a):''}<h2 style="margin:0 0 6px">${list.length} asset${list.length===1?'':'s'}</h2>${list.length?`<ul class="list">${list.map(x=>`<li><button class="row" data-act="selAsset" data-id="${x.id}" aria-pressed="${id===x.id}">${stIcon(x.status,22)}<span class="grow"><b>${esc(x.name)}</b><br><span class="sub">${x.id} · ${WW.types[x.type]} · ${WW.statusLabel[x.status]}</span></span></button></li>`).join('')}</ul>`:`<div class="empty card">${ic('map')}<p><b>No assets match these filters.</b></p><button class="btn" data-act="clearF">Clear filters</button></div>`}</section></div>`)}
function assetCard(a){const s=WW.sensors.find(x=>x.assetId===a.id);const wos=WW.wos.filter(w=>w.asset===a.id&&w.status!=='done');
 return`<div class="card" style="margin-bottom:10px"><div class="pagehead" style="margin-bottom:6px"><h2>${esc(a.name)}</h2>${stChip(a.status)}</div><p class="hint">${a.id} · ${WW.types[a.type]} · Owner: ${esc(a.owner)} · Installed ${a.inst} · Last maintenance ${a.last}</p>${s?`<p style="margin:6px 0 0"><span class="chip sim">SIMULATED SENSOR — test environment</span> ${chip(s.state,sensLabel[s.state])}</p>${spark(s)}`:'<p class="hint">No sensor installed. Status comes from community reports and inspections.</p>'}${wos.length?`<p>${wos.map(w=>`<a href="#/console/orders">${w.id}</a> ${chip(w.pri,w.pri)}`).join(' ')}</p>`:''}<a class="btn sm" href="#/console/asset/${a.id}">Open full asset record</a></div>`}
function assetView(id){const a=asset(id);if(!a)return consoleShell('map',`<div class="empty card"><h1>Asset not found</h1><a href="#/console/map">Back to map</a></div>`);
 const ss=WW.sensors.filter(x=>x.assetId===id);const h=WW.history[id]||[];const rs=WW.reports.filter(r=>r.asset===id);
 return consoleShell('asset',`<p><a href="#/console/map">← Map & assets</a></p><div class="pagehead"><h1>${esc(a.name)}</h1>${stChip(a.status)}<span class="chip sim">Synthetic demonstration data</span></div>
 <div class="grid2"><section class="card"><h2>Registry record</h2><table><tbody>${[['Asset ID',a.id],['Type',WW.types[a.type]],['Owner / manager',a.owner],['Location (synthetic)',`-1.${2800+a.x*3}, 36.${8000+a.y*9}`],['Installed',a.inst],['Last maintenance',a.last],['WPDx export','status_id, water_source, install_year, lat/lon mapped (see spec)']].map(([k,v])=>`<tr><th scope="row">${k}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table></section>
 <section class="card"><h2>Sensors</h2>${ss.length?ss.map(s=>`<div style="margin-bottom:8px"><b>${s.id}</b> · ${s.kind} (${s.unit}) ${chip(s.state,sensLabel[s.state])}<br><span class="chip sim">SIMULATED SENSOR — test environment</span> <span class="hint">last reading ${s.mins>=60?mins(s.mins)+' ago':s.mins+' min ago'}</span>${spark(s)}</div>`).join(''):'<div class="empty">No sensor installed on this asset.</div>'}</section></div>
 <section class="card" style="margin-top:12px"><h2>Maintenance history</h2>${h.length?`<ul class="tl">${h.map(x=>`<li><b>${x[0]}</b> — ${esc(x[1])}<br><span class="hint">${esc(x[2])} · ${x[3]?kes(x[3]):'No cost recorded'}</span></li>`).join('')}</ul>`:'<div class="empty">No maintenance recorded yet.</div>'}</section>
 <section class="card" style="margin-top:12px"><h2>Linked reports</h2>${rs.length?rs.map(r=>`<p>${r.id} · ${WW.cats[r.cat].en} · ${ago(r.at)} · ${r.status==='linked'?`linked to ${r.wo}`:'new'}</p>`).join(''):'<div class="empty">No reports.</div>'}</section>`)}
function reportsView(){
 const rs=[...WW.reports].sort((a,b)=>(b.cat==='contam')-(a.cat==='contam')||b.at-a.at);
 return consoleShell('reports',`<div class="pagehead"><h1>Outage reports — triage</h1><span class="chip sim">Synthetic demonstration data</span></div>
 ${rs.some(r=>r.cat==='contam'&&r.status==='new')?`<div class="alertbar" role="alert">${ic('alert')}<div><b>Contamination concern pinned to top.</b> Treat as P1. A report is a community observation, not a lab result. Follow the utility's water-quality escalation procedure; notify the public-health officer.</div></div>`:''}
 <ul class="list" style="max-height:none">${rs.map(r=>{const a=asset(r.asset);const c=r.cat==='contam';return`<li><div class="row" style="cursor:default;flex-wrap:wrap;${c?'border-color:var(--contam);border-width:2px':''}">${ic(WW.cats[r.cat].ico)}<span class="grow"><b>${r.id} · ${WW.cats[r.cat].en}</b> ${c?chip('contam','High priority — contamination'):''}<br><span class="sub">${esc(a.name)} · ${ago(r.at)} · ${r.lang==='sw'?'Kiswahili':'English'} · ${r.photo?'photo attached':'no photo'} · ${esc(r.gps)}</span><br>${esc(r.text)}</span>${r.status==='linked'?chip('linked','Linked '+r.wo):`<button class="btn sm pri" data-act="mkWO" data-id="${r.id}">Create work order</button><button class="btn sm" data-act="dupe" data-id="${r.id}">Mark duplicate</button><button class="btn sm danger" data-act="reject" data-id="${r.id}">Reject…</button>`}</div></li>`}).join('')}</ul>`)}
function ordersView(){
 const cols=['new','assigned','in_progress','parts','done'];
 return consoleShell('orders',`<div class="pagehead"><h1>Work orders</h1><span class="chip sim">Synthetic demonstration data</span></div><p class="hint">Keyboard: use the buttons on each card to assign or advance status. Drag-and-drop is not required.</p>
 <div class="board">${cols.map(c=>{const ws=WW.wos.filter(w=>w.status===c);return`<section class="col" aria-label="${woLabel[c]}"><h3>${woLabel[c]} <span class="num">${ws.length}</span></h3>${ws.length?ws.map(w=>woCard(w)).join(''):'<div class="empty hint">None</div>'}</section>`}).join('')}</div>`)}
function woCard(w){const a=asset(w.asset);const t=tech(w.tech);const total=w.mats.reduce((s,m)=>s+m.c*(m.q||1),0)||w.cost;
 return`<article class="wo ${w.pri}"><div><b>${w.id}</b> ${chip(w.pri,w.pri==='P1'?'P1 urgent':w.pri==='P2'?'P2 high':'P3 routine')}</div><div>${esc(w.title)}</div><div class="hint">${esc(a.name)}</div>${slaTxt(w)}<div class="hint">${t?ic('user')+' '+esc(t.name):'Unassigned'} ${total?'· '+kes(total):''}</div>${w.status!=='done'?`<div style="display:flex;gap:6px;flex-wrap:wrap"><label class="sr" for="as-${w.id}">Assign technician for ${w.id}</label><select id="as-${w.id}" data-act="assign" data-id="${w.id}" style="min-height:36px;width:auto"><option value="">Assign…</option>${WW.techs.map(x=>`<option value="${x.id}" ${w.tech===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button class="btn sm" data-act="advance" data-id="${w.id}">Advance →</button></div>`:''}</article>`}
function sensorsView(){
 const bad=WW.sensors.filter(s=>s.state!=='ok');
 return consoleShell('sensors',`<div class="pagehead"><h1>Sensor health</h1><span class="chip sim">SIMULATED SENSOR — test environment</span></div>
 <div class="kpis"><div class="kpi"><b>${WW.sensors.length}</b><span>Simulated devices</span></div><div class="kpi"><b>${WW.sensors.length-bad.length}</b><span>Reporting normally</span></div><div class="kpi"><b>${bad.length}</b><span>Need attention</span></div></div>
 ${bad.length?`<div class="alertbar" style="border-color:var(--warn);background:var(--warn-soft)" role="alert">${ic('alert')}<div><span style="color:var(--warn)"><b>${bad.length} sensors need attention.</b> Missing, late or flat-lined readings are never shown as zero. The asset status stays "unknown" or "degraded" until a person confirms.</span></div></div>`:''}
 <div class="card tablewrap"><table><caption class="sr">Sensor health table</caption><thead><tr><th>Device</th><th>Asset</th><th>Kind</th><th>Health</th><th>Last reading</th><th>Trend (24 h)</th></tr></thead><tbody>${WW.sensors.map(s=>`<tr><td class="mono">${s.id}<br><span class="chip sim">SIMULATED</span></td><td><a href="#/console/asset/${s.assetId}">${esc(asset(s.assetId).name)}</a></td><td>${s.kind} (${s.unit})</td><td>${chip(s.state,sensLabel[s.state])}</td><td>${s.mins>=60?mins(s.mins)+' ago':s.mins+' min ago'}</td><td style="min-width:180px">${spark(s,180,44)}</td></tr>`).join('')}</tbody></table></div>
 <div class="card" style="margin-top:12px"><h2>Ingestion (test environment)</h2><p class="hint">HTTP POST /v1/ingest and MQTT topic ww/&lt;org&gt;/&lt;device&gt;/telemetry. Each message carries device ID, sequence number, timestamp, and an HMAC-SHA256 signature over the body using the per-device key. Messages with a bad signature or replayed sequence are rejected and logged. Store-and-forward batches are accepted with original timestamps.</p><button class="btn" data-act="simMsg">Send simulated test reading</button><ul id="msgs" class="mono hint"></ul></div>`)}
const bars=(vals,labels,u,h=150)=>{const mx=Math.max(...vals)*1.15;const w=Math.floor(300/vals.length);return`<svg viewBox="0 0 320 ${h+30}" class="spark" style="height:auto" role="img" aria-label="Bar chart: ${labels.map((l,i)=>l+' '+vals[i]).join(', ')}">${[0,.5,1].map(f=>`<line x1="10" x2="315" y1="${h-f*h*.87}" y2="${h-f*h*.87}" stroke="var(--rule)"/>`).join('')}${vals.map((v,i)=>`<g><rect x="${14+i*w}" y="${h-v/mx*h}" width="${w-8}" height="${v/mx*h}" fill="var(--chart-a)" rx="2"/><text x="${14+i*w+(w-8)/2}" y="${h-v/mx*h-4}" text-anchor="middle" font-size="11" font-weight="700" fill="var(--ink)">${v}</text><text x="${14+i*w+(w-8)/2}" y="${h+14}" text-anchor="middle" font-size="10" fill="var(--ink-2)">${labels[i]}</text></g>`).join('')}</svg>`};
function analyticsView(){const an=WW.an;const tc=an.cost.reduce((s,c)=>s+c[1],0);
 const pts=an.mttr.map((v,i)=>[20+i*48,120-(v-15)/15*100]);
 return consoleShell('analytics',`<div class="pagehead"><h1>Analytics</h1><span class="chip sim">Synthetic demonstration data — not real performance</span></div>
 <div class="kpis"><div class="kpi"><b>63</b><span>Reported outages (7 wks)</span></div><div class="kpi"><b>23.2 h</b><span>Mean time to repair (W47)</span></div><div class="kpi"><b>4</b><span>Assets with 2+ repeat failures</span></div><div class="kpi"><b>136 h</b><span>Total downtime (top 5)</span></div><div class="kpi"><b>${kes(tc*100000)}</b><span>Maintenance cost (7 wks)</span></div></div>
 <div class="charts"><section class="card"><h2>Reported outages per week</h2>${bars(an.outages,an.weeks)}<details><summary>Data table</summary><table><tbody>${an.weeks.map((w,i)=>`<tr><th scope="row">${w}</th><td>${an.outages[i]}</td></tr>`).join('')}</tbody></table></details></section>
 <section class="card"><h2>Mean time to repair (hours)</h2><svg viewBox="0 0 340 150" class="spark" style="height:auto" role="img" aria-label="Line chart of MTTR in hours by week: ${an.mttr.join(', ')}"><path d="${pts.map((p,i)=>(i?'L':'M')+p[0]+' '+p[1]).join(' ')}" fill="none" stroke="var(--chart-b)" stroke-width="3"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="var(--chart-b)"/><text x="${p[0]}" y="${p[1]-9}" text-anchor="middle" font-size="11" font-weight="700" fill="var(--ink)">${an.mttr[i]}</text><text x="${p[0]}" y="145" text-anchor="middle" font-size="10" fill="var(--ink-2)">${an.weeks[i]}</text>`).join('')}</svg></section>
 <section class="card"><h2>Repeat failures</h2><table><thead><tr><th>Asset</th><th>Failures</th><th>Pattern</th></tr></thead><tbody>${an.repeat.map(r=>`<tr><td><a href="#/console/asset/${r[0]}">${esc(r[1])}</a></td><td class="num">${r[2]}</td><td>${esc(r[3])}</td></tr>`).join('')}</tbody></table></section>
 <section class="card"><h2>Downtime by asset (hours)</h2>${an.downtime.map(d=>`<div style="display:flex;align-items:center;gap:8px;margin:6px 0"><span style="width:150px">${esc(d[0])}</span><span style="flex:1;background:var(--sunken);border-radius:4px"><span style="display:block;height:16px;border-radius:4px;background:var(--chart-a);width:${d[1]/61*100}%"></span></span><b class="num">${d[1]}</b></div>`).join('')}</section>
 <section class="card"><h2>Maintenance cost by category (KES '000)</h2>${an.cost.map(d=>`<div style="display:flex;align-items:center;gap:8px;margin:6px 0"><span style="width:110px">${d[0]}</span><span style="flex:1;background:var(--sunken);border-radius:4px"><span style="display:block;height:16px;border-radius:4px;background:var(--chart-b);width:${d[1]/14.7*100}%"></span></span><b class="num">${d[1]}</b></div>`).join('')}<p class="hint">Revenue water / NRW is a utility-performance metric needing metered production and billing data; not computed here.</p></section></div>`)}
function auditView(){return consoleShell('audit',`<div class="pagehead"><h1>Audit log</h1><span class="chip sim">Simulated</span></div><p class="hint">Append-only in production. Every triage, assignment, status change and cost entry is recorded with actor and time.</p><div class="card tablewrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Object</th></tr></thead><tbody>${st.audit.map(a=>`<tr><td class="mono">${a.t.toLocaleTimeString('en-GB')}</td><td>${esc(a.who)}</td><td>${esc(a.act)}</td><td class="mono">${esc(a.obj)}</td></tr>`).join('')}</tbody></table></div>`)}
// ---- community report
const L={en:{title:'Report a water problem',s1:'1. What is wrong?',s2:'2. Add a photo (optional)',s3:'3. Where?',photo:'Take photo',gps:'Use my location',send:'Send report',off:'You are offline. Reports will be sent when you are back online.',queued:'Saved on this phone. It will send when you have signal.',thanks:'Thank you. Report sent.',safe:'Safety first',missing:'Choose a problem type',loc:'Choose a location or use GPS',nearest:'Nearest water point',another:'Report another'},
 sw:{title:'Ripoti tatizo la maji',s1:'1. Tatizo ni nini?',s2:'2. Ongeza picha (si lazima)',s3:'3. Mahali?',photo:'Piga picha',gps:'Tumia eneo langu',send:'Tuma ripoti',off:'Huna mtandao. Ripoti zitatumwa ukipata mtandao.',queued:'Imehifadhiwa kwenye simu. Itatumwa ukipata mtandao.',thanks:'Asante. Ripoti imetumwa.',safe:'Usalama kwanza',missing:'Chagua aina ya tatizo',loc:'Chagua mahali au tumia GPS',nearest:'Kituo cha maji cha karibu',another:'Ripoti nyingine'}};
function reportView(){const r=st.rep,t=L[st.lang];const isC=r.cat==='contam';
 const head=`<div class="phonehead">${ic('drop')} WaterWatch <span class="spacer"></span><button class="btn" data-act="lang" aria-label="${st.lang==='en'?'Badilisha kwa Kiswahili':'Switch to English'}">${st.lang==='en'?'Kiswahili':'English'}</button></div>`;
 const off=`<div class="offbar ${st.offline?"":"on"}" role="status">${st.offline?ic('wifi-off')+' '+t.off:ic('check')+' Online'} <span class="spacer"></span><button class="btn sm" data-act="offline" aria-pressed="${st.offline}">${st.offline?'Go online (sim)':'Go offline (sim)'}</button></div>`;
 if(r.done)return`<div class="phonewrap"><main id="main" class="phone" tabindex="-1">${head}${off}<div class="phonebody"><div class="card" style="text-align:center"><h1 style="color:var(--ok)">${ic('check')} ${r.done.queued?t.queued:t.thanks}</h1><p class="num">Ref ${r.done.id}</p><p class="timer">Prototype timer: report completed in ${r.done.secs} s (target < 45 s)</p></div>${r.done.contam?safety(t):''}<button class="btn pri big" data-act="again">${t.another}</button>${st.queue.length?queueBox():''}</div></main></div>`;
 return`<div class="phonewrap"><main id="main" class="phone" tabindex="-1">${head}${off}<div class="phonebody"><h1>${t.title}</h1><div class="steps" aria-hidden="true"><i class="on"></i><i class="${r.cat?'on':''}"></i><i class="${r.cat&&r.asset?'on':''}"></i></div>
 <fieldset style="border:0;padding:0;margin:0"><legend style="font-weight:800;margin-bottom:6px">${t.s1}</legend><div class="catgrid">${Object.entries(WW.cats).map(([k,c])=>`<button class="cat c-${k}" data-act="cat" data-k="${k}" aria-pressed="${r.cat===k}">${ic(c.ico)}${c[st.lang]}</button>`).join('')}</div></fieldset>
 ${isC?safety(t):''}
 <section><h2>${t.s2}</h2><button class="photo btn" data-act="photo" style="width:100%">${r.photo?ic('check')+' Photo added (simulated, 148 KB after compression)':ic('cam')+' '+t.photo}</button></section>
 <section><h2>${t.s3}</h2><button class="btn" data-act="gps" aria-pressed="${r.gps}">${ic('pin')} ${r.gps?'GPS: -1.2931, 36.8210 (±12 m) — simulated':t.gps}</button><label for="wp" style="margin-top:8px">${t.nearest}</label><select id="wp" data-act="wp"><option value="">—</option>${WW.assets.filter(a=>['borehole','kiosk','waterpoint'].includes(a.type)).map(a=>`<option value="${a.id}" ${r.asset===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select><div id="rerr" class="err" role="alert"></div></section>
 <button class="btn pri big" data-act="send">${t.send}</button><p class="timer">Verified reporters only. Your phone number is stored with the report; see privacy notice. Photos are resized on the phone.</p>${st.queue.length?queueBox():''}</div></main></div>`}
const safety=t=>st.lang==='en'?`<div class="safety" role="alert"><h3>${ic('alert')} Safety first</h3><ul><li>Do not drink, cook with or give this water to children or animals until the utility says it is safe.</li><li>Use another safe source. Bottled or treated water if you can.</li><li>Boiling may not remove chemical or fuel contamination.</li><li>If anyone feels sick, go to the nearest clinic and tell them about the water.</li></ul><p>This report is marked URGENT and sent to the utility now. It is a community report, not a lab test.</p></div>`:`<div class="safety" role="alert"><h3>${ic('alert')} Usalama kwanza</h3><ul><li>Usinywe, usipikie wala usiwape watoto au mifugo maji haya hadi kampuni ya maji itakapothibitisha ni salama.</li><li>Tumia chanzo kingine salama.</li><li>Kuchemsha huenda kusiondoe uchafu wa kemikali au mafuta.</li><li>Mtu akiumwa, nenda kliniki iliyo karibu na uwaambie kuhusu maji.</li></ul><p>Ripoti hii imewekwa DHARURA na inatumwa sasa. Si matokeo ya maabara. (Tafsiri inahitaji kukaguliwa na mzungumzaji wa Kiswahili.)</p></div>`;
const queueBox=()=>`<div class="card" role="status"><b>${ic('clock')} ${st.queue.length} report${st.queue.length>1?'s':''} waiting to send</b><ul>${st.queue.map(q=>`<li>${q.id} · ${WW.cats[q.cat].en}</li>`).join('')}</ul><button class="btn sm" data-act="sync" ${st.offline?'disabled':''}>Send now</button></div>`;
// ---- technician
function techView(id){const me='T-2';const mine=WW.wos.filter(w=>w.tech===me&&w.status!=='done').sort((a,b)=>a.slaEnd-b.slaEnd);
 const head=`<div class="phonehead">${ic('wrench')} Technician <span class="spacer"></span><span class="chip sim" style="background:var(--surface)">Amina W. (synthetic)</span></div>`;
 if(!id)return`<div class="phonewrap"><main id="main" class="phone" tabindex="-1">${head}<div class="phonebody"><h1>My jobs (${mine.length})</h1><p class="hint">Sorted by SLA. Works offline; changes sync later.</p>${mine.length?`<ul class="list" style="max-height:none">${mine.map(w=>`<li><a class="row" style="text-decoration:none;color:inherit;display:flex" href="#/tech/${w.id}"><span class="grow"><b>${w.id}</b> ${chip(w.pri,w.pri)}<br>${esc(w.title)}<br><span class="sub">${esc(asset(w.asset).name)}</span><br>${slaTxt(w)}</span></a></li>`).join('')}</ul>`:`<div class="empty card">${ic('check')}<p><b>No open jobs.</b></p></div>`}<h2>Completed today</h2><p class="hint">${WW.wos.filter(w=>w.tech===me&&w.status==='done').length} job(s)</p></div></main></div>`;
 const w=WW.wos.find(x=>x.id===id);if(!w)return`<div class="phonewrap"><main id="main" class="phone">${head}<div class="phonebody empty">Job not found. <a href="#/tech">Back</a></div></main></div>`;
 const a=asset(w.asset);const order=['assigned','in_progress','parts','done'];const total=w.mats.reduce((s,m)=>s+m.c*m.q,0);
 return`<div class="phonewrap"><main id="main" class="phone" tabindex="-1">${head}<div class="phonebody"><a href="#/tech">← My jobs</a><h1>${w.id} ${chip(w.pri,w.pri)}</h1><p>${esc(w.title)}</p><div class="card"><b>${esc(a.name)}</b><br><span class="hint">${WW.types[a.type]} · ${stChip(a.status)}</span><br>${slaTxt(w)}</div>
 <button class="btn big" data-act="navigate" data-id="${a.id}">${ic('nav')} Navigate (opens maps app — simulated)</button>
 <section><h2>Status</h2><ol class="stepper">${order.map(s=>{const i=order.indexOf(w.status),j=order.indexOf(s);return`<li class="${j<i?'done':j===i?'cur':''}">${j<i?ic('check'):j===i?ic('wrench'):ic('clock')} ${woLabel[s]}${j===i?' (current)':''}</li>`}).join('')}</ol>${w.status!=='done'?`<div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap"><button class="btn" data-act="tstat" data-id="${w.id}" data-s="in_progress">Start work</button><button class="btn" data-act="tstat" data-id="${w.id}" data-s="parts">Need parts</button></div>`:''}</section>
 <section><h2>Materials & costs</h2>${w.mats.length?`<table><tbody>${w.mats.map(m=>`<tr><td>${esc(m.n)} ×${m.q}</td><td class="num">${kes(m.c*m.q)}</td></tr>`).join('')}<tr><th scope="row">Total</th><td class="num"><b>${kes(total)}</b></td></tr></tbody></table>`:'<p class="hint">Nothing recorded yet.</p>'}${w.status!=='done'?`<button class="btn" data-act="addMat" data-id="${w.id}">+ Add material or labour</button>`:''}</section>
 <section><h2>Completion</h2><p class="hint">A completion photo is required to close the job.</p><button class="btn" data-act="cphoto" data-id="${w.id}" aria-pressed="${!!w.cphoto}">${w.cphoto?ic('check')+' Completion photo added (simulated)':ic('cam')+' Take completion photo'}</button><div id="cerr" class="err" role="alert"></div><button class="btn pri big" data-act="complete" data-id="${w.id}" ${w.status==='done'?'disabled':''} style="margin-top:8px">${w.status==='done'?'Completed':'Mark complete'}</button></section></div></main></div>`}
// ---- router
function route(){const h=location.hash.replace(/^#\/?/,'').split('/');const [a,b,c]=h;let body;
 if(!a)body=home();
 else if(a==='console'){body=({map:()=>mapView(c),'':()=>mapView(),undefined:()=>mapView(),reports:reportsView,orders:ordersView,sensors:sensorsView,analytics:analyticsView,audit:auditView,asset:()=>assetView(c)}[b]||mapView)()}
 else if(a==='report')body=reportView();else if(a==='tech')body=techView(b);else body=home();
 const ae=document.activeElement&&document.activeElement.id;
 $('#app').innerHTML=top(h)+(a==='report'||a==='tech'?'':'')+body;
 if(a==='')$('#app').innerHTML=top(['home'])+body;
 if(ae&&$('#'+ae)&&ae!=='dlg'){try{$('#'+ae).focus()}catch(e){}}
}
const rerender=()=>{const y=scrollY;route();scrollTo(0,y)};
window.addEventListener('hashchange',()=>{route();scrollTo(0,0);const m=$('#main');if(m)m.focus({preventScroll:true})});
// ---- actions
const mkId=()=>'R-'+(2042+WW.reports.length+st.queue.length+Math.floor(Math.random()*0)).toString();
document.addEventListener('input',e=>{const a=e.target.dataset.act;if(a==='fQ'){st.q=e.target.value;rerender();const q=$('#fq');q.focus();q.setSelectionRange(q.value.length,q.value.length)}});
document.addEventListener('change',e=>{const el=e.target,a=el.dataset.act;if(!a)return;
 if(a==='fStatus'){st.fStatus=el.value;rerender()}
 if(a==='fType'){st.fType=el.value;rerender()}
 if(a==='wp'){st.rep.asset=el.value||null;rerender()}
 if(a==='assign'){const w=WW.wos.find(x=>x.id===el.dataset.id);w.tech=el.value||null;if(w.tech&&w.status==='new')w.status='assigned';log('Dispatcher (synthetic)','Assigned '+(w.tech?tech(w.tech).name:'nobody'),w.id);toast(w.id+' assigned');rerender()}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el||el.tagName==='SELECT'||el.tagName==='INPUT')return;const a=el.dataset.act,id=el.dataset.id;
 if(a==='theme'){st.theme=document.documentElement.dataset.theme==='dark'||(!document.documentElement.dataset.theme&&matchMedia('(prefers-color-scheme:dark)').matches)?'light':'dark';theme()}
 if(a==='selAsset'){location.hash='#/console/map/'+id}
 if(a==='clearF'){st.fStatus='all';st.fType='all';st.q='';rerender()}
 if(a==='mkWO'){const r=WW.reports.find(x=>x.id===id);const c=r.cat==='contam';openDlg(`<form class="dlgf" method="dialog" id="woform"><h2>Create work order from ${r.id}</h2><p class="hint">${esc(asset(r.asset).name)} · ${WW.cats[r.cat].en}</p><div><label for="wpri">Priority</label><select id="wpri"><option value="P1" ${c?'selected':''}>P1 urgent (SLA 2 h)</option><option value="P2" ${c?'':'selected'}>P2 high (SLA 24 h)</option><option value="P3">P3 routine (SLA 72 h)</option></select></div><div><label for="wtech">Technician</label><select id="wtech"><option value="">Assign later</option>${WW.techs.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div>${c?'<p class="safety">Contamination: also notify the water-quality officer and public-health contact. Do not state the cause until tested.</p>':''}<div class="acts"><button type="button" class="btn" data-act="closeDlg">Cancel</button><button type="button" class="btn pri" data-act="saveWO" data-id="${r.id}">Create work order</button></div></form>`)}
 if(a==='closeDlg')closeDlg();
 if(a==='saveWO'){const r=WW.reports.find(x=>x.id===id);const pri=$('#wpri').value,t=$('#wtech').value;const n='WO-'+(321+WW.wos.filter(w=>+w.id.slice(3)>320).length);const sla={P1:120,P2:1440,P3:4320}[pri];WW.wos.push({id:n,asset:r.asset,title:WW.cats[r.cat].en+': '+asset(r.asset).name,pri,status:t?'assigned':'new',tech:t||null,slaMin:sla,slaEnd:Date.now()+sla*60000,cost:0,mats:[],src:r.id});r.status='linked';r.wo=n;log('Dispatcher (synthetic)',`Created ${n} (${pri}) from ${r.id}`,n);closeDlg();toast(n+' created');rerender()}
 if(a==='dupe'){const r=WW.reports.find(x=>x.id===id);r.status='linked';r.wo='duplicate';log('Dispatcher (synthetic)','Marked duplicate',id);toast(id+' marked duplicate');rerender()}
 if(a==='reject'){openDlg(`<form class="dlgf" id="rjf"><h2>Reject ${id}</h2><div><label for="rr">Reason (required, shown to reporter)</label><textarea id="rr" rows="3"></textarea><div class="err" id="rre" role="alert"></div></div><div class="acts"><button type="button" class="btn" data-act="closeDlg">Cancel</button><button type="button" class="btn danger" data-act="doReject" data-id="${id}">Reject report</button></div></form>`)}
 if(a==='doReject'){const v=$('#rr').value.trim();if(v.length<5){$('#rre').textContent='Enter a reason of at least 5 characters.';return}const i=WW.reports.findIndex(x=>x.id===id);WW.reports.splice(i,1);log('Dispatcher (synthetic)','Rejected report: '+v,id);closeDlg();toast(id+' rejected');rerender()}
 if(a==='advance'){const w=WW.wos.find(x=>x.id===id);const o=['new','assigned','in_progress','parts','done'];if(w.status==='new'&&!w.tech){toast('Assign a technician first');return}w.status=o[Math.min(4,o.indexOf(w.status)+1)];log('Dispatcher (synthetic)','Status → '+woLabel[w.status],id);rerender()}
 if(a==='simMsg'){const u=$('#msgs');u.insertAdjacentHTML('afterbegin',`<li>SIMULATED SENSOR — test environment · SIM-FL-01 seq ${1000+u.children.length} flow=${(200+Math.random()*20).toFixed(1)} m³/h · signature OK</li>`);log('SIM-FL-01','Ingested simulated reading','SIM-FL-01');toast('Simulated reading accepted')}
 // community
 if(a==='lang'){st.lang=st.lang==='en'?'sw':'en';rerender()}
 if(a==='offline'){st.offline=!st.offline;rerender()}
 if(a==='cat'){if(!st.rep.t0)st.rep.t0=Date.now();st.rep.cat=el.dataset.k;rerender()}
 if(a==='photo'){if(!st.rep.t0)st.rep.t0=Date.now();st.rep.photo=true;rerender()}
 if(a==='gps'){if(!st.rep.t0)st.rep.t0=Date.now();st.rep.gps=true;if(!st.rep.asset)st.rep.asset='A-006';rerender()}
 if(a==='send'){const r=st.rep,t=L[st.lang];const err=!r.cat?t.missing:(!r.gps&&!r.asset)?t.loc:'';if(err){$('#rerr').textContent=err;return}
  const secs=Math.max(1,Math.round((Date.now()-(r.t0||Date.now()))/1000));const rid='R-'+(2042+WW.reports.length+st.queue.length);const rec={id:rid,asset:r.asset||'A-006',cat:r.cat,text:'(new report from prototype)',lang:st.lang,photo:r.photo,at:Date.now(),status:'new',reporter:'Verified reporter (you, simulated)',gps:'-1.2931, 36.8210 (±12 m)'};
  if(st.offline){st.queue.push(rec);st.rep={cat:null,photo:false,asset:null,gps:false,step:0,t0:null,done:{id:rid,secs,queued:true,contam:r.cat==='contam'}}}else{WW.reports.push(rec);log('Community reporter (simulated)','Submitted report',rid);st.rep={cat:null,photo:false,asset:null,gps:false,step:0,t0:null,done:{id:rid,secs,contam:r.cat==='contam'}}}
  rerender()}
 if(a==='again'){st.rep={cat:null,photo:false,asset:null,gps:false,step:0,t0:null,done:null};rerender()}
 if(a==='sync'){st.queue.forEach(q=>{WW.reports.push(q);log('Community reporter (simulated)','Queued report synced',q.id)});st.queue=[];toast('Queued reports sent');rerender()}
 // tech
 if(a==='navigate')toast('Simulated: would open the maps app to '+asset(id).name);
 if(a==='tstat'){const w=WW.wos.find(x=>x.id===id);w.status=el.dataset.s;log('Amina W. (synthetic)','Status → '+woLabel[w.status],id);toast(woLabel[w.status]);rerender()}
 if(a==='addMat'){openDlg(`<form class="dlgf" id="mf"><h2>Add material or labour</h2><div><label for="mn">Item</label><input id="mn"></div><div><label for="mq">Quantity</label><input id="mq" type="number" min="1" value="1" inputmode="numeric"></div><div><label for="mc">Unit cost (KES)</label><input id="mc" type="number" min="0" inputmode="numeric"></div><div class="err" id="me" role="alert"></div><div class="acts"><button type="button" class="btn" data-act="closeDlg">Cancel</button><button type="button" class="btn pri" data-act="saveMat" data-id="${id}">Save</button></div></form>`)}
 if(a==='saveMat'){const n=$('#mn').value.trim(),q=+$('#mq').value,c=+$('#mc').value;if(!n||!(q>=1)||!(c>=0)||$('#mc').value===''){$('#me').textContent='Enter an item, a quantity of 1 or more, and a unit cost.';return}const w=WW.wos.find(x=>x.id===id);w.mats.push({n,q,c:Math.round(c*100)});log('Amina W. (synthetic)',`Added ${n} ×${q}`,id);closeDlg();toast('Saved');rerender()}
 if(a==='cphoto'){const w=WW.wos.find(x=>x.id===id);w.cphoto=true;rerender()}
 if(a==='complete'){const w=WW.wos.find(x=>x.id===id);if(!w.cphoto){$('#cerr').textContent='Add a completion photo before closing this job.';return}w.status='done';log('Amina W. (synthetic)','Completed (photo attached)',id);toast(id+' completed');location.hash='#/tech'}
});
document.addEventListener("keydown",e=>{const m=e.target.closest&&e.target.closest("g.marker");if(m&&(e.key==="Enter"||e.key===" ")){e.preventDefault();location.hash="#/console/map/"+m.dataset.id}});
// SLA timers refresh
setInterval(()=>{if(/console\/orders|tech/.test(location.hash)&&!$('#dlg').open&&!/INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName)){const y=scrollY;route();scrollTo(0,y)}},30000);
route();
window.WWTEST={st,route};
})();
